import React, { useState, useEffect } from 'react';
import { 
  ExclamationTriangleIcon, 
  InformationCircleIcon, 
  CheckCircleIcon,
  XMarkIcon,
  BellIcon,
  ClockIcon,
  EyeIcon,
  EyeSlashIcon
} from '@heroicons/react/24/outline';
import api from '../services/api';
import { useNotification } from '../hooks/useNotification';
import { formatDistanceToNow } from 'date-fns';
import { es } from 'date-fns/locale';

const AlertsPanel = ({ domainId = null, showHeader = true, maxAlerts = null }) => {
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all'); // all, unread, high, medium, low
  const { showNotification } = useNotification();

  useEffect(() => {
    fetchAlerts();
  }, [domainId, filter]);

  const fetchAlerts = async () => {
    try {
      setLoading(true);
      let url = '/api/alerts/';
      const params = new URLSearchParams();

      if (domainId) {
        params.append('domain', domainId);
      }

      if (filter !== 'all') {
        if (filter === 'unread') {
          params.append('status', 'active');
        } else {
          params.append('severity', filter);
        }
      }

      if (maxAlerts) {
        params.append('limit', maxAlerts);
      }

      if (params.toString()) {
        url += '?' + params.toString();
      }

      const response = await api.get(url);
      setAlerts(response.data.results || response.data);
    } catch (error) {
      console.error('Error fetching alerts:', error);
      showNotification('Error al cargar las alertas', 'error');
    } finally {
      setLoading(false);
    }
  };

  const handleAcknowledgeAlert = async (alertId) => {
    try {
      await api.post(`/api/alerts/${alertId}/acknowledge/`);
      setAlerts(alerts.map(alert => 
        alert.id === alertId 
          ? { ...alert, status: 'acknowledged' }
          : alert
      ));
      showNotification('Alerta marcada como vista', 'success');
    } catch (error) {
      console.error('Error acknowledging alert:', error);
      showNotification('Error al marcar la alerta', 'error');
    }
  };

  const handleResolveAlert = async (alertId) => {
    try {
      await api.post(`/api/alerts/${alertId}/resolve/`);
      setAlerts(alerts.filter(alert => alert.id !== alertId));
      showNotification('Alerta resuelta', 'success');
    } catch (error) {
      console.error('Error resolving alert:', error);
      showNotification('Error al resolver la alerta', 'error');
    }
  };

  const getSeverityIcon = (severity) => {
    switch (severity) {
      case 'high':
        return <ExclamationTriangleIcon className="h-5 w-5 text-red-500" />;
      case 'medium':
        return <ExclamationTriangleIcon className="h-5 w-5 text-yellow-500" />;
      case 'low':
        return <InformationCircleIcon className="h-5 w-5 text-blue-500" />;
      default:
        return <InformationCircleIcon className="h-5 w-5 text-gray-500" />;
    }
  };

  const getSeverityColor = (severity) => {
    switch (severity) {
      case 'high':
        return 'bg-red-50 border-red-200';
      case 'medium':
        return 'bg-yellow-50 border-yellow-200';
      case 'low':
        return 'bg-blue-50 border-blue-200';
      default:
        return 'bg-gray-50 border-gray-200';
    }
  };

  const getSeverityBadge = (severity) => {
    const colors = {
      high: 'bg-red-100 text-red-800',
      medium: 'bg-yellow-100 text-yellow-800',
      low: 'bg-blue-100 text-blue-800'
    };

    const labels = {
      high: 'Alta',
      medium: 'Media',
      low: 'Baja'
    };

    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
        colors[severity] || 'bg-gray-100 text-gray-800'
      }`}>
        {labels[severity] || severity}
      </span>
    );
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'active':
        return <BellIcon className="h-4 w-4 text-red-500" />;
      case 'acknowledged':
        return <EyeIcon className="h-4 w-4 text-yellow-500" />;
      case 'resolved':
        return <CheckCircleIcon className="h-4 w-4 text-green-500" />;
      default:
        return <ClockIcon className="h-4 w-4 text-gray-500" />;
    }
  };

  const filteredAlerts = alerts.filter(alert => {
    if (filter === 'all') return true;
    if (filter === 'unread') return alert.status === 'active';
    return alert.severity === filter;
  });

  const unreadCount = alerts.filter(alert => alert.status === 'active').length;

  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
        {showHeader && (
          <h3 className="text-lg font-medium text-gray-900 mb-4">Alertas</h3>
        )}
        <div className="animate-pulse space-y-4">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="flex items-center space-x-4">
              <div className="rounded-full bg-gray-200 h-10 w-10"></div>
              <div className="flex-1 space-y-2">
                <div className="h-4 bg-gray-200 rounded w-3/4"></div>
                <div className="h-3 bg-gray-200 rounded w-1/2"></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200">
      {showHeader && (
        <div className="px-6 py-4 border-b border-gray-200">
          <div className="flex items-center justify-between">
            <div className="flex items-center">
              <h3 className="text-lg font-medium text-gray-900">Alertas</h3>
              {unreadCount > 0 && (
                <span className="ml-2 inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800">
                  {unreadCount} nuevas
                </span>
              )}
            </div>

            {/* Filtros */}
            <div className="flex items-center space-x-2">
              <select
                value={filter}
                onChange={(e) => setFilter(e.target.value)}
                className="text-sm border-gray-300 rounded-md focus:ring-primary-500 focus:border-primary-500"
              >
                <option value="all">Todas</option>
                <option value="unread">No leídas</option>
                <option value="high">Alta prioridad</option>
                <option value="medium">Media prioridad</option>
                <option value="low">Baja prioridad</option>
              </select>
            </div>
          </div>
        </div>
      )}

      <div className="p-6">
        {filteredAlerts.length === 0 ? (
          <div className="text-center py-8">
            <BellIcon className="mx-auto h-12 w-12 text-gray-400" />
            <h3 className="mt-2 text-sm font-medium text-gray-900">
              {filter === 'unread' ? 'No hay alertas nuevas' : 'No hay alertas'}
            </h3>
            <p className="mt-1 text-sm text-gray-500">
              {filter === 'unread' 
                ? 'Todas las alertas han sido revisadas'
                : 'No se han generado alertas para este dominio'
              }
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredAlerts.map((alert) => (
              <div
                key={alert.id}
                className={`border rounded-lg p-4 transition-colors ${
                  getSeverityColor(alert.severity)
                } ${
                  alert.status === 'active' ? 'ring-1 ring-opacity-50' : ''
                }`}
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-start space-x-3 flex-1">
                    <div className="flex-shrink-0 mt-0.5">
                      {getSeverityIcon(alert.severity)}
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center space-x-2 mb-1">
                        <h4 className="text-sm font-medium text-gray-900 truncate">
                          {alert.title}
                        </h4>
                        {getSeverityBadge(alert.severity)}
                        {getStatusIcon(alert.status)}
                      </div>

                      <p className="text-sm text-gray-600 mb-2">
                        {alert.message}
                      </p>

                      <div className="flex items-center text-xs text-gray-500 space-x-4">
                        <span className="flex items-center">
                          <ClockIcon className="h-3 w-3 mr-1" />
                          {formatDistanceToNow(new Date(alert.created_at), {
                            addSuffix: true,
                            locale: es
                          })}
                        </span>

                        {alert.domain_name && (
                          <span>Dominio: {alert.domain_name}</span>
                        )}

                        {alert.rule_name && (
                          <span>Regla: {alert.rule_name}</span>
                        )}
                      </div>

                      {/* Datos adicionales */}
                      {alert.additional_data && Object.keys(alert.additional_data).length > 0 && (
                        <div className="mt-2 p-2 bg-white bg-opacity-50 rounded text-xs">
                          <details>
                            <summary className="cursor-pointer text-gray-600 hover:text-gray-800">
                              Ver detalles
                            </summary>
                            <div className="mt-1 space-y-1">
                              {Object.entries(alert.additional_data).map(([key, value]) => (
                                <div key={key} className="flex justify-between">
                                  <span className="font-medium">{key}:</span>
                                  <span>{typeof value === 'object' ? JSON.stringify(value) : value}</span>
                                </div>
                              ))}
                            </div>
                          </details>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Acciones */}
                  <div className="flex items-center space-x-2 ml-4">
                    {alert.status === 'active' && (
                      <button
                        onClick={() => handleAcknowledgeAlert(alert.id)}
                        className="inline-flex items-center p-1.5 border border-transparent rounded text-xs font-medium text-yellow-700 bg-yellow-100 hover:bg-yellow-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-yellow-500"
                        title="Marcar como vista"
                      >
                        <EyeIcon className="h-3 w-3" />
                      </button>
                    )}

                    {alert.status !== 'resolved' && (
                      <button
                        onClick={() => handleResolveAlert(alert.id)}
                        className="inline-flex items-center p-1.5 border border-transparent rounded text-xs font-medium text-green-700 bg-green-100 hover:bg-green-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                        title="Resolver alerta"
                      >
                        <CheckCircleIcon className="h-3 w-3" />
                      </button>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Enlace para ver todas las alertas */}
        {maxAlerts && filteredAlerts.length >= maxAlerts && (
          <div className="mt-4 text-center">
            <a
              href="/alerts"
              className="text-sm text-primary-600 hover:text-primary-800 font-medium"
            >
              Ver todas las alertas →
            </a>
          </div>
        )}
      </div>
    </div>
  );
};

export default AlertsPanel;
